// Discrete-event simulation: 3 backends, one of them half as fast (an older instance type).
// Each backend serves its queue FIFO, one request at a time.
function mulberry32(seed) { // tiny seeded PRNG so every run prints the same numbers
  return () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const SPEEDS = [1, 1, 0.5];          // requests per ms each backend can complete
const WEIGHTS = [2, 2, 1];           // for weighted round robin, proportional to speed
const N = 20000;
const LOAD = 0.85;                   // arrivals at 85% of total capacity (2.5 req/ms)

const algorithms = {
  roundRobin: (s) => s.count++ % 3,
  weightedRR: (s) => { const seq = [0, 1, 0, 1, 2]; return seq[s.count++ % seq.length]; },
  random: (s) => Math.floor(s.rand() * 3),
  leastConn: (s, active) => active.indexOf(Math.min(...active)),
  powerOfTwo: (s, active) => {      // sample two distinct backends, keep the less loaded one
    const a = Math.floor(s.rand() * 3);
    const b = (a + 1 + Math.floor(s.rand() * 2)) % 3;
    return active[a] <= active[b] ? a : b;
  },
};

function simulate(pick) {
  const rand = mulberry32(42);       // same arrivals for every algorithm
  const state = { count: 0, rand: mulberry32(7) };
  const inFlight = SPEEDS.map(() => []); // finish times of requests queued or in service
  const lastFinish = SPEEDS.map(() => 0);
  const served = [0, 0, 0];
  const latencies = [];
  let t = 0;
  for (let i = 0; i < N; i++) {
    t += -Math.log(1 - rand()) / (LOAD * 2.5);     // Poisson arrivals
    const work = -Math.log(1 - rand());            // exponential job size, mean 1
    inFlight.forEach((q, k) => { inFlight[k] = q.filter((f) => f > t); });
    const k = pick(state, inFlight.map((q) => q.length));
    const finish = Math.max(t, lastFinish[k]) + work / SPEEDS[k];
    lastFinish[k] = finish;
    inFlight[k].push(finish);
    served[k]++;
    latencies.push(finish - t);
  }
  latencies.sort((x, y) => x - y);
  const mean = latencies.reduce((a, b) => a + b, 0) / N;
  const p99 = latencies[Math.floor(N * 0.99)];
  const share = served.map((c) => Math.round((100 * c) / N) + '%').join('/');
  return { mean: mean.toFixed(1), p99: p99.toFixed(1), share };
}

console.log('algorithm   mean_ms  p99_ms  share(fast/fast/slow)');
for (const [name, pick] of Object.entries(algorithms)) {
  const r = simulate(pick);
  console.log(name.padEnd(11), r.mean.padStart(7), r.p99.padStart(7), ' ', r.share);
}
// algorithm   mean_ms  p99_ms  share(fast/fast/slow)
// roundRobin    682.8  4043.4   33%/33%/33%   <- slow backend gets 0.71 req/ms but can do 0.5: queue grows forever
// weightedRR      6.0    26.3   40%/40%/20%   <- right weights fix it, but only while the weights stay right
// random        623.9  3811.0   34%/34%/33%
// leastConn       3.6    17.8   42%/39%/20%   <- adapts with no configuration
// powerOfTwo      4.3    20.1   40%/38%/22%   <- nearly as good, while checking only 2 backends

// Connection draining from the backend's side:
// on SIGTERM, fail the readiness check, wait for the LB to notice, finish in-flight work, exit.
const http = require('node:http');

const LB_NOTICE_MS = 100; // demo value. In production: health interval x unhealthy threshold (often 10-30 s)
let draining = false;

const server = http.createServer((req, res) => {
  if (req.url === '/ready') {                       // the load balancer's health check
    res.writeHead(draining ? 503 : 200).end(draining ? 'draining' : 'ok');
    return;
  }
  setTimeout(() => res.end('report done'), 300);    // a slow 300 ms request
});

function shutdown() {
  draining = true;                                  // 1. readiness fails, so the LB stops routing new requests here
  console.log('SIGTERM: readiness now failing');
  setTimeout(() => {
    server.close(() => {                            // 3. stop accepting, then wait for in-flight requests
      console.log('in-flight work finished, exiting');
      process.exit(0);
    });
    server.closeIdleConnections();                  //    and drop idle keep-alive sockets
  }, LB_NOTICE_MS);                                 // 2. keep serving until the LB has noticed
  setTimeout(() => process.exit(1), 30_000).unref(); // 4. hard deadline, shorter than the LB/orchestrator's
}
process.on('SIGTERM', shutdown);

server.listen(0, async () => {
  const base = `http://localhost:${server.address().port}`;
  const report = fetch(`${base}/report`).then((r) => r.text());
  await new Promise((r) => setTimeout(r, 50));      // the request is mid-flight...
  process.kill(process.pid, 'SIGTERM');             // ...when the orchestrator stops the instance
  const probe = await fetch(`${base}/ready`);
  console.log('health check during drain:', probe.status);
  console.log('in-flight response:', await report);
});
// SIGTERM: readiness now failing
// health check during drain: 503
// in-flight response: report done
// in-flight work finished, exiting

