// Why retries need exponential backoff WITH jitter, plus a retry budget.
function mulberry32(seed) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(1);
const BASE = 100, CAP = 2000; // ms

const noJitter = (attempt) => Math.min(CAP, BASE * 2 ** attempt);
const fullJitter = (attempt) => rand() * Math.min(CAP, BASE * 2 ** attempt); // AWS "full jitter"

// 1,000 clients all fail at t=0 (a backend restarted) and retry 3 times.
// Count the worst 10 ms window of retry traffic the recovering backend receives.
function peakPer10ms(delayFn) {
  const buckets = new Map();
  for (let c = 0; c < 1000; c++) {
    let t = 0;
    for (let attempt = 0; attempt < 3; attempt++) {
      t += delayFn(attempt);
      const b = Math.floor(t / 10);
      buckets.set(b, (buckets.get(b) ?? 0) + 1);
    }
  }
  return Math.max(...buckets.values());
}
console.log('no jitter, peak retries per 10 ms:  ', peakPer10ms(noJitter));   // 1000  (every client retries at 100, 300, 700 ms)
console.log('full jitter, peak retries per 10 ms:', peakPer10ms(fullJitter)); // 162   (same retries, spread out)

// Retry budget: retries may add at most 10% on top of normal requests (like Envoy/Finagle budgets).
class RetryBudget {
  constructor(ratio) { this.ratio = ratio; this.requests = 0; this.retries = 0; }
  onRequest() { this.requests++; }
  canRetry() {
    if (this.retries < this.requests * this.ratio) { this.retries++; return true; }
    return false;
  }
}
const budget = new RetryBudget(0.1);
let allowed = 0;
for (let i = 0; i < 500; i++) {          // an outage: all 500 requests fail
  budget.onRequest();
  if (budget.canRetry()) allowed++;
}
console.log(`outage: ${allowed} of 500 failures retried (load x${((500 + allowed) / 500).toFixed(1)}, not x4)`);
// outage: 50 of 500 failures retried (load x1.1, not x4)
